"""A2A server configuration for Mantle projects.

Mantle declares the inbound A2A server in a top-level ``a2a_server`` block of
``integrations.yml``. It is deliberately not an entry under ``channels:``: A2A
is a protocol surface served on the main Sanic port, not an input channel. The
block shares its shape with the CALM ``endpoints.yml`` block, with a Mantle
spelling for the engine-specific option ``include_default_skills``. Presence
of the block turns A2A on; a missing block leaves it off. There is no
``enabled`` key.

``${VAR}`` references are expanded when the file is read. A JWT ``secret`` is
kept as its ``${VAR}`` reference so a literal secret is still rejected.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Mapping, Optional, Union

import pydantic
from pydantic import ConfigDict, Field, model_validator

from rasa.core.a2a_server.config import (
    A2A_SERVER_KEY,
    A2AConfigSource,
    A2AServerSettings,
)
from rasa.core.a2a_server.config_sources import integrations_file_declares_a2a_server
from rasa.core.a2a_server.startup import A2AServerStartup
from rasa.exceptions import ValidationError
from rasa.shared.engine_version import MANTLE_ENGINE_VERSION
from rasa.shared.exceptions import RasaException
from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE
from rasa.shared.utils.yaml import read_yaml_file

_CALM_ONLY_KEYS: dict[str, str] = {
    "include_conversation_repair": "include_default_skills",
}


class MantleA2AServerConfig(A2AServerSettings):
    """Top-level ``a2a_server`` block of ``integrations.yml``."""

    model_config = ConfigDict(
        extra="forbid", hide_input_in_errors=True, populate_by_name=True
    )

    include_default_skills: bool = Field(
        default=False,
        description=(
            "When ``true``, customized default skills may be advertised on the "
            "AgentCard so the builder decides whether the orchestrator or this "
            "agent owns them. Engine-managed, disabled, and hidden skills are "
            "never advertised."
        ),
    )

    @model_validator(mode="before")
    @classmethod
    def reject_calm_only_keys(cls, data: Any) -> Any:
        """Point builders who copy a CALM block at the Mantle spelling."""
        if not isinstance(data, Mapping):
            return data
        for calm_key, mantle_key in _CALM_ONLY_KEYS.items():
            if calm_key in data:
                raise ValueError(
                    f"'{calm_key}' is a CALM option for 'endpoints.yml'. In "
                    f"'{MANTLE_INTEGRATIONS_FILE}' use '{mantle_key}' instead."
                )
        return data


class MantleA2AServerStartup(A2AServerStartup):
    """Mantle binding. Default-skill advertising belongs to the Mantle adapter.

    The shared settings model drops this flag. It stays on the Mantle startup
    type so a CALM binding cannot carry it.
    """

    include_default_skills: bool = False


class MantleA2AConfigSource(A2AConfigSource):
    """Reads the top-level ``a2a_server`` block of a project's ``integrations.yml``.

    Does not touch ``channels:``. The file is read lazily on first access and
    the parsed block is cached for the lifetime of the source.
    """

    engine_version = MANTLE_ENGINE_VERSION
    file_name = MANTLE_INTEGRATIONS_FILE

    def __init__(self, project_root: Union[str, Path]) -> None:
        """Create a source for the ``integrations.yml`` under *project_root*."""
        self._integrations_file = Path(project_root) / MANTLE_INTEGRATIONS_FILE
        self._config: Optional[MantleA2AServerConfig] = None
        self._parsed = False

    @property
    def config(self) -> Optional[MantleA2AServerConfig]:
        """Parsed block, or ``None`` when the file or the block is absent."""
        if not self._parsed:
            self._parsed = True
            raw_block = self._read_raw_block()
            if raw_block is not None:
                self._config = _parse_mantle_a2a_server_block(
                    raw_block, self._integrations_file
                )
        return self._config

    def is_declared(self) -> bool:
        """Whether the file declares an ``a2a_server`` block."""
        return integrations_file_declares_a2a_server(self._integrations_file.parent)

    def load(self) -> Optional[A2AServerSettings]:
        """Return runtime settings, or ``None`` when A2A is absent."""
        config = self.config
        if config is None:
            return None
        return config.to_settings()

    def to_startup(self, settings: A2AServerSettings) -> MantleA2AServerStartup:
        """Carry ``include_default_skills`` on the Mantle startup type."""
        config = self.config
        return MantleA2AServerStartup(
            engine_version=self.engine_version,
            settings=settings,
            include_default_skills=(
                config.include_default_skills if config is not None else False
            ),
        )

    def _read_raw_block(self) -> Any:
        if not self._integrations_file.is_file():
            return None
        raw = read_yaml_file(self._integrations_file, expand_env_vars=True)
        if not isinstance(raw, Mapping):
            return None
        return raw.get(A2A_SERVER_KEY)


def _parse_mantle_a2a_server_block(
    raw_block: Any, integrations_file: Path
) -> MantleA2AServerConfig:
    if not isinstance(raw_block, Mapping):
        raise ValidationError(
            code="validation.a2a_server.invalid_mantle_config",
            event_info=(
                f"'{A2A_SERVER_KEY}' in '{integrations_file}' must be a mapping, "
                f"but got '{type(raw_block).__name__}'."
            ),
        )
    try:
        return MantleA2AServerConfig.model_validate(dict(raw_block))
    except RasaException:
        raise
    except pydantic.ValidationError as error:
        raise ValidationError(
            code="validation.a2a_server.invalid_mantle_config",
            event_info=(
                f"Invalid '{A2A_SERVER_KEY}' configuration in "
                f"'{integrations_file}': {error}"
            ),
        ) from error
